export const PSLF_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/pslf-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getPslfStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(PSLF_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
